si":["sports","adventure","wildlife"],"commission":"guide","wells":["activities","stay"],"draw_rank":23,"tier_absent_reason":"does-not-compete","source":"https://realestate.grandisleresort.com/?p=1392","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Farmer''s Cay and the Mile-Long Sandbar","blurb":"\"A popular destination for yachters and boaters, thanks in part to the popular Mile-Long Sandbar located just south of the island\"; served by Farmer''s Cay Airport","si":["sailing","yacht","tropical"],"wells":["activities","fly"],"draw_rank":24,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/the-exumas","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Santanna''s and the Little Exuma family kitchens","blurb":"Ministry of Tourism: \"Three unique dining experiences. One destination. Each of these small, family-owned businesses on Little Exuma are a success in their own right - but it''s when they work together that they truly shine.\"","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":25,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/islands/the-exumas","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"February Point","blurb":"\"a freestyle out-island lifestyle in a private destination marina community\" - a gated community on Great Exuma \"just minutes from the conveniences of downtown George Town and a 20-minute scenic ride from the airport\"; overwater penthouses and oceanfront residences for rent; Marina Village; +1 242-336-2660","si":["yacht","family","group","tropical"],"commission":"hotel","wells":["activities","fly","stay"],"draw_rank":26,"tier_absent_reason":"not-established","source":"https://www.februarypoint.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Shirley''s Seafood Restaurant at the Fish Fry","blurb":"At The Fish Fry on Queen''s Highway, Great Exuma - conch chowder, grouper and snapper; \"Thursday to Monday: 1:00 PM to 9:00 PM | Closed Tuesday and Wednesday\" (review dated May 26, 2023 - hours may have changed)","si":["culinary","culture"],"commission":"venue","wells":["eat"],"draw_rank":27,"tier_absent_reason":"does-not-compete","source":"https://thebulkheadseat.com/?p=5693","accessed":"2026-10-02"},{"name":"Regatta Point","blurb":"\"an all suites hotel ... on a point of land that is almost totally surrounded by the exquisite, crystal blue waters of Elizabeth Harbour\"; six suites with full kitchens; on-site manager in George Town 242-336-2206","si":["tropical","senior","sailing"],"commission":"hotel","wells":["activities","stay"],"draw_rank":28,"tier_absent_reason":"not-established","source":"https://www.regattapointbahamas.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Exuma Sailing Club","blurb":"\"In the quiet cove off Elizabeth Harbour, calm waters become a classroom for a team of young sailors keeping the tradition of Bahamian sloop sailing alive.\"","si":["culture","sailing","family"],"wells":["activities","move","stay"],"draw_rank":29,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/the-exumas","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (sailing club) - operator for sailing days and regatta entries","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a sailing club - it sells sailing days and hosts the regatta"}],"faq":[{"q":"What is worth doing in The Exumas?","a":"Swimming Pigs at Big Major Cay — swim with the world-famous pigs.","source":"https://www.bahamas.com/experiences/official-home-swimming-pigs"},{"q":"Can you fly direct to Exuma, Bahamas?","a":"Yes. Grand Isle Resort lists direct flights into Exuma International Airport: \"Delta Airlines from Atlanta\", \"American Airlines from Charlotte every Saturday\", \"Bahamas Air, Aztec Air from Ft. Lauderdale\", \"American Airlines from Miami\" and \"Air Canada from Toronto\", adding that \"frequency of scheduled flights varies by season\". This is a hotel''s list, not a carrier''s timetable.","source":"https://www.grandisleresort.com/getting-here.htm","accessed":"2026-10-02"},{"q":"Do you need a passport for Exuma, Bahamas?","a":"Yes. The Bahamas Department of Immigration requires visitors to \"present a passport that is valid for at least six months (passport cards will not be accepted)\" and to \"possess a valid return ticket/ means of departing The Bahamas\". It adds that \"admittance is not automatic\".","source":"https://www.immigration.gov.bs/entry-requirements/before-your-arrival/","accessed":"2026-10-02"},{"q":"What is the Exuma airport code?","a":"GGT. The Ministry of Tourism names Exuma International Airport (GGT) as \"the primary gateway into The Exumas\", on Great Exuma \"just a few miles from its main settlement of George Town\". Staniel Cay Airport in the cays is TYM.","source":"https://www.bahamas.com/islands/the-exumas","accessed":"2026-10-02"},{"q":"When was the Exuma Regatta in 2026?","a":"The 70th anniversary National Family Island Regatta took place April 22-25, 2026 in Elizabeth Harbour near George Town, with A, B, C and E-Class sloops racing.","source":"https://www.sailingscuttlebutt.com/?p=134608","accessed":"2026-10-02"},{"q":"When is the Exuma Regatta in 2027?","a":"The Ministry of Tourism lists the National Family Island Regatta for \"Apr 22, 2027\" in George Town. It shows only that start date.","source":"https://www.bahamas.com/events/national-family-island-regatta","accessed":"2026-10-02"},{"q":"When is Sandals Exuma reopening?","a":"No reopening date was found. Sandals Emerald Bay closed in August 2024 to become Beaches Exuma. On August 18, 2025 The Tribune reported \"there is still no active construction on site\" and that the timeline had moved from 6-8 months to 12-15 months. The Sandals site could not be read for a current status.","source":"http://www.tribune242.com/news/2025/aug/18/why-the-silence-on-sandals-exuma","accessed":"2026-10-02"},{"q":"Where should I stay in Exuma to swim with the pigs?","a":"The pigs are on Big Major Cay, which \"is only accessible by boat\". Staniel Cay is the nearest base with its own airport: Staniel Cay Yacht Club promotes the pigs and Thunderball Grotto, Embrace Resort sits \"just steps from Staniel Cay Airport\", and Fowl Cay gives each villa a powerboat. From Great Exuma, Exuma Water Sports runs a full-day tour with hotel pickups.","source":"https://www.bahamas.com/experiences/official-home-swimming-pigs","accessed":"2026-10-02"},{"q":"Is there a ferry from Exuma to Stocking Island?","a":"Stocking Island is reached by boat. The Ministry of Tourism says it is \"easily reachable by boat from Elizabeth Harbour\", and Chat ''N'' Chill describes itself as \"a short water taxi ride from George Town\". No ferry timetable was found on the pages read.","source":"https://www.bahamas.com/experiences/stocking-island","accessed":"2026-10-02"},{"q":"Can you get to Exuma from Nassau?","a":"Yes, including as a day trip. Bahamas Air Tours offers \"a day trip from Nassau to Staniel Cay in the Exumas\" for the pigs, sharks, iguanas, sandbars and Thunderball Grotto at $850. Staniel Cay Adventures also lists Nassau among its departure points. A scheduled Nassau to Exuma flight or ferry timetable was not read on a carrier page this session.","source":"https://www.bahamasairtours.com/","accessed":"2026-10-02"}],"seo":{"meta_title":"Exuma Bahamas: Swimming Pigs, Grotto & Cays","meta_description":"Swim with the famous pigs at Big Major Cay, snorkel Thunderball Grotto and dive the Exuma Cays. Plan your Exumas adventure. When to go and how.","slug":"exuma-bahamas","primary_keyword":"Exuma swimming pigs tour","long_tail":["Staniel Cay Thunderball Grotto snorkel","Exuma Cays Land and Sea Park diving","Compass Cay nurse sharks","Big Major Cay Pig Beach","Exuma liveaboard"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"liveaboard","status":"live-route"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"The Exumas, Bahamas"},"geo":{"lat":23.5167,"lng":-75.8333},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"andros-bahamas","jewels":3,"si":["diveglobal"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"long-island-bahamas","jewels":3,"si":["tropical","expedition","diveglobal"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 2)
